import{z as A,x as d,o as r,c as l,q as E,j as c,D as e,d as t,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"引用计数与环","description":"","frontmatter":{"title":"引用计数与环","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/refcount-cycles.md","filePath":"cs/refcount-cycles.md","lastUpdated":1791063341000}'),i={name:"cs/refcount-cycles.md"};function B(C,a,p,h,_,u){const o=d("Mermaid");return r(),l("div",null,[a[2]||(a[2]=E('<h1 id="引用计数与环" tabindex="-1">引用计数与环 <a class="header-anchor" href="#引用计数与环" aria-label="Permalink to &quot;引用计数与环&quot;">​</a></h1><div class="epigraph"><p>计数到零立即回收，局部性好；对象图一旦成环，计数永远到不了零。环要弱引用、分代或备份跟踪。</p><footer>—— 据 Collins, A Method for Overlapping and Erasure of Lists, CACM 1960；Bacon et al., Concurrent Cycle Collection；[运行时 GC](/cs/runtime-gc) 整理</footer></div><p><a href="/cs/allocator-structures">上一课</a> 假定 <code>free</code> 被正确叫到。<a href="/cs/runtime-gc">运行时 GC</a> 已从标记谈论自动回收。<a href="/cs/persistent-path-copy">路径复制</a> 的共享靠计数或 GC。<a href="/cs/rcu-data-structures">RCU</a> 不用对象图计数。本课是数据结构进阶最后一课：引用计数作为结构不变量，以及环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个对象 <code>rc</code>：指针复制 <code>+1</code>，销毁 <code>-1</code>，零则把内嵌指针再减并归还分配器。优点：即时、可预测、易与<a href="/cs/hazard-pointer">hazard</a> 外的单线程所有权混用。环：双向图、父带子、子指父，<code>rc\\ge 1</code> 永真。缺口不是再讲 buddy，而是<strong>计数不变量推不出可达性</strong>；环是图结构问题。</p><p><span class="marginnote">Collins 1960 早期引用计数。Bacon 等并发环收集把试验删除与备份跟踪结合起来。弱引用不增加 <code>rc</code>，打破所有者环。</span></p><p><span class="marginnote">数字实例：<code>A.next = B</code> 且 <code>B.prev = A</code>，两者 <code>rc</code> 各为 1。程序删掉最后指向 A 的引用时，A 的 <code>rc</code> 只从 2 减到 1——B 那条回边还在撑着。两个对象从此既不可达也死不掉，这就是环泄漏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对策：(1) 所有者边强、回边弱；(2) 周期检测（试验性减、对候选环 DFS）；(3) 混合：分代复制/标记扫环，计数管无环。原子 <code>rc</code> 的递增开销与伪共享是并发税。溢出与饱和计数是实现细节。</p>',9)),(r(),c(n,null,{default:e(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PTR%5B%22%E5%A4%8D%E5%88%B6%E6%8C%87%E9%92%88%22%5D%20--%3E%20INC%5B%22rc%20%2B%3D%201%22%5D%0A%20%20DROP%5B%22%E9%94%80%E6%AF%81%E6%8C%87%E9%92%88%22%5D%20--%3E%20DEC%5B%22rc%20-%3D%201%22%5D%0A%20%20DEC%20--%3E%20Z%5B%22rc%20%3D%200%3A%20%E5%9B%9E%E6%94%B6%22%5D%0A%20%20CYC%5B%22%E7%8E%AF%22%5D%20--%3E%20NZ%5B%22rc%20%E6%B0%B8%E4%B8%8D%200%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>与持久结构：共享子树正是 <code>rc&gt;1</code>；无环 DAG 计数正确。与 LSM/无锁：那些结构的节点寿命用 HP/RCU，不靠对象 <code>rc</code> 图。</p><p><span class="marginnote">直觉类比：强引用像「同住一间屋」，计数归零就退租；弱引用像通讯录里存了个号码——记得对方但不同住、不占名额。把环上至少一条边改成弱引用，这间屋就退得掉了。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数据进阶课序在此封口：序列区间、对数堆与空间树、字符串、草图、持久与无锁，最后把「对象何时死」接回分配器。后课算法进阶从<a href="/cs/scc-tarjan">强连通</a> 另开，不在这里把 Tarjan SCC 当环收集实现抄完——图算法课再收。</p><p>不要把引用计数写成 Transformer 注意力；就是堆对象图。</p><p><span class="marginnote">常见误区：「计数 \\gt 0 = 有人用」只在无环图上成立。初学者容易拿 <code>rc</code> 当存活性判据写缓存或观察者注册；一旦对象成环，泄漏的就不只是内存，还有挂在环上的回调与锁。</span></p>',6)),(r(),c(n,null,{default:e(()=>[s(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUS%5B%22%E7%96%91%E4%BC%BC%E7%8E%AF%EF%BC%9A%E5%A4%96%E9%83%A8%E5%8F%AF%E8%A7%81%20rc%20%E4%B8%8E%E5%86%85%E9%83%A8%E5%BC%95%E7%94%A8%E6%95%B0%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%5D%20--%3E%20TRIAL%5B%22%E8%AF%95%E9%AA%8C%E5%88%A0%E9%99%A4%EF%BC%9A%E5%AF%B9%E5%80%99%E9%80%89%E5%AF%B9%E8%B1%A1%E5%81%87%E8%AE%BE%E6%80%A7%20rc-1%22%5D%0A%20%20TRIAL%20--%3E%20SCAN%5B%22%E6%B2%BF%E5%86%85%E9%83%A8%E5%BC%95%E7%94%A8%E5%90%91%E4%B8%8B%E6%89%AB%EF%BC%8C%E5%90%8C%E6%AD%A5%E5%81%87%E8%AE%BE%E6%80%A7%E5%87%8F%22%5D%0A%20%20SCAN%20--%3E%20Z%7B%22%E6%9C%89%E5%AF%B9%E8%B1%A1%E8%AE%A1%E6%95%B0%E5%BD%92%200%3F%22%7D%0A%20%20Z%20--%3E%7C%22%E6%98%AF%22%7C%20COLLECT%5B%22%E7%A1%AE%E8%AE%A4%E7%9C%9F%E7%8E%AF%EF%BC%9A%E6%95%B4%E4%BD%93%E5%9B%9E%E6%94%B6%22%5D%0A%20%20Z%20--%3E%7C%22%E5%90%A6%22%7C%20KEEP%5B%22%E4%BB%8D%E8%A2%AB%E5%A4%96%E9%83%A8%E5%BC%95%E7%94%A8%EF%BC%9A%E6%81%A2%E5%A4%8D%E8%AE%A1%E6%95%B0%EF%BC%8C%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整并发环收集证明。不进入限价簿对象。标记-清除/复制 GC 细节见运行时课，本课只对照：跟踪能收环，计数默认不能。</p><p>后课默认：无环 DAG 可用引用计数；有环要弱边或跟踪 GC。数据结构进阶主干到此结束；下一课从<a href="/cs/scc-tarjan">强连通分量</a>起算法进阶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引用计数：零即收，即时；环会泄漏。</li><li>弱引用或跟踪收集破环。</li><li>本课序结束；图算法课序另起。</li><li>出处：Collins, <em>CACM</em>, 1960；Bacon 等环收集；Wilson/GC 文献与 runtime-gc 课。</li></ul>',5))])}const m=A(i,[["render",B]]);export{f as __pageData,m as default};
